def solve(s):
    """Check if brackets in string s are balanced and properly nested.
    Considers (), [], {} and ignores other characters.
    """
    stack = []
    opening = set('({[')
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

