def solve(s):
    """Return True if brackets in *s* are balanced.
    Supports (), [], {} and ignores all other characters. If *s* is not a
    string, returns False.
    """
    if not isinstance(s, str):
        return False
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    opening = set(pairs.values())
    for ch in s:
        if ch in opening:
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

